const RETIRE_CURRENT_BOOK =
  "UPDATE books SET status = 'past', finished_on = current_date WHERE status = 'current'";

// Starting a new book moves the current one into the history.
export async function startBook(book: { title: string; author: string; link: string }) {
  await transaction(async (client) => {
    await client.query(RETIRE_CURRENT_BOOK);
    await client.query(
      "INSERT INTO books (title, author, link, status) VALUES ($1, $2, $3, 'current')",
      [book.title, book.author, book.link],
