// ---- Suggestions and votes ----

export type Suggestion = {
  id: number;
  title: string;
  author: string;
  link: string;
  suggested_by: number | null;
  suggested_by_name: string | null;
  votes: number;
};

// Oldest first, so the list doesn't reshuffle as votes come in.
export function listSuggestions(): Promise<Suggestion[]> {
  return all(
    `SELECT b.id, b.title, b.author, b.link, b.suggested_by, m.name AS suggested_by_name,
            (SELECT count(*)::int FROM votes v WHERE v.book_id = b.id) AS votes
     FROM books b LEFT JOIN members m ON m.id = b.suggested_by
     WHERE b.status = 'suggested'
     ORDER BY b.id`,
  );
}

// The suggestion this member is voting for in the current round, if any.
export async function getVote(memberId: number): Promise<number | undefined> {
  const row = await one<{ book_id: number }>(
    `SELECT v.book_id FROM votes v JOIN books b ON b.id = v.book_id
     WHERE v.member_id = $1 AND b.status = 'suggested'`,
    [memberId],
  );
  return row?.book_id;
}

export async function suggestBook(book: {
  title: string;
  author: string;
  link: string;
  memberId: number;
}): Promise<{ ok: true; id: number } | { ok: false; error: "already_suggested" }> {
  try {
    const row = await one<{ id: number }>(
      `INSERT INTO books (title, author, link, status, suggested_by)
       VALUES ($1, $2, $3, 'suggested', $4) RETURNING id`,
      [book.title, book.author, book.link, book.memberId],
    );
    return { ok: true, id: row!.id };
  } catch (err) {
    if ((err as { constraint?: string }).constraint === "suggested_title_unique") {
      return { ok: false, error: "already_suggested" };
    }
    throw err;
  }
}

// Casting a vote replaces the member's previous one. Returns false if the book isn't up for a
// vote. FOR SHARE makes a concurrent pickSuggestion wait, so a vote can't land on a book that
// was just picked.
export async function castVote(memberId: number, bookId: number): Promise<boolean> {
  const row = await one(
    `INSERT INTO votes (member_id, book_id)
     SELECT $1, id FROM books WHERE id = $2 AND status = 'suggested' FOR SHARE
     ON CONFLICT (member_id) DO UPDATE SET book_id = excluded.book_id
     RETURNING book_id`,
    [memberId, bookId],
  );
  return row !== undefined;
}

// Pass memberId to only delete the book if that member suggested it. Votes for it go too.
export async function removeSuggestion(bookId: number, memberId?: number) {
  await all(
    `DELETE FROM books WHERE id = $1 AND status = 'suggested'
     AND ($2::integer IS NULL OR suggested_by = $2)`,
    [bookId, memberId ?? null],
  );
}

// Closes the round: the suggestion becomes the current book, the old one moves to the history,
// and everyone's vote is cleared. Other suggestions stay up for the next round.
export async function pickSuggestion(bookId: number): Promise<boolean> {
  return transaction(async (client) => {
    await client.query(RETIRE_CURRENT_BOOK);
    const picked = await client.query(
      "UPDATE books SET status = 'current' WHERE id = $1 AND status = 'suggested'",
      [bookId],
    );
    if (picked.rowCount === 0) throw new NotASuggestion();
    await client.query("DELETE FROM votes");
    return true;
  }).catch((err) => {
    if (err instanceof NotASuggestion) return false;
    throw err;
  });
}

class NotASuggestion extends Error {}

