export type DueReminder = {
  meeting_id: number;
  starts_at: string;
  location: string;
  notes: string;
  book_title: string | null;
  member_id: number;
  name: string;
  email: string;
  rsvp: RsvpStatus | null;
};

// Everyone with an email who hasn't said no and hasn't been reminded yet, for meetings on
// `date` ('2026-11-12', club-local).
export function listDueReminders(date: string): Promise<DueReminder[]> {
  return all(
    `SELECT m.id AS meeting_id, m.starts_at, m.location, m.notes, b.title AS book_title,
            p.id AS member_id, p.name, p.email, r.status AS rsvp
     FROM meetings m
     LEFT JOIN books b ON b.id = m.book_id
     CROSS JOIN members p
     LEFT JOIN rsvps r ON r.meeting_id = m.id AND r.member_id = p.id
     WHERE left(m.starts_at, 10) = $1
       AND p.email IS NOT NULL
       AND r.status IS DISTINCT FROM 'no'
       AND NOT EXISTS (
         SELECT 1 FROM meeting_reminders s
         WHERE s.meeting_id = m.id AND s.member_id = p.id AND s.starts_at = m.starts_at)
     ORDER BY m.starts_at, m.id, lower(p.name)`,
    [date],
  );
}

// Returns false if this reminder was already claimed, e.g. by an overlapping run.
export async function claimReminder(meetingId: number, memberId: number, startsAt: string) {
  const row = await one(
    `INSERT INTO meeting_reminders (meeting_id, member_id, starts_at) VALUES ($1, $2, $3)
     ON CONFLICT DO NOTHING RETURNING 1`,
    [meetingId, memberId, startsAt],
  );
  return row !== undefined;
}

// Undoes a claim when sending failed, so the next run retries it.
export async function releaseReminder(meetingId: number, memberId: number, startsAt: string) {
  await all(
    "DELETE FROM meeting_reminders WHERE meeting_id = $1 AND member_id = $2 AND starts_at = $3",
    [meetingId, memberId, startsAt],
  );
}
