import { claimReminder, listDueReminders, releaseReminder, type DueReminder } from "./db";
import { sendEmail, type Email } from "./email";
import { formatMeetingTime } from "./format";

// The club's date for `now` plus one day, as 'YYYY-MM-DD'. Meeting times are club-local
// wall-clock time, so "tomorrow" has to be computed in the club's timezone too.
export function tomorrowIn(timeZone: string, now: Date): string {
  const today = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(now);
  const [y, m, d] = today.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d + 1)).toISOString().slice(0, 10);
}

const RSVP_LINE = {
  going: "You said you're going.",
  maybe: "You said maybe. Let everyone know if you can make it.",
  none: "You haven't RSVP'd yet.",
};

export function reminderEmail(r: DueReminder): Email {
  const when = formatMeetingTime(r.starts_at);
  const lines = [
    `Hi ${r.name},`,
    "",
    `Book club meets tomorrow, ${when}.`,
    r.book_title && `Book: ${r.book_title}`,
    r.location && `Where: ${r.location}`,
    r.notes && `Notes: ${r.notes}`,
    "",
    RSVP_LINE[r.rsvp ?? "none"],
  ];
  return {
    to: r.email,
    subject: `Book club tomorrow: ${when}`,
    text: lines.filter((line) => line !== null && line !== "" || line === "").join("\n"),
  };
}

// Emails everyone coming to (or undecided about) tomorrow's meetings. Safe to run as often
// as you like: each member gets one reminder per meeting date.
export async function sendMeetingReminders(now = new Date()): Promise<{ date: string; sent: number }> {
  const date = tomorrowIn(process.env.CLUB_TIMEZONE || "UTC", now);
  let sent = 0;
  for (const r of await listDueReminders(date)) {
    if (!(await claimReminder(r.meeting_id, r.member_id, r.starts_at))) continue;
    try {
      await sendEmail(reminderEmail(r));
      sent++;
    } catch (err) {
      await releaseReminder(r.meeting_id, r.member_id, r.starts_at);
      console.error(`Reminder to member ${r.member_id} failed`, err);
    }
  }
  return { date, sent };
}
